window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-95339ed87f7902d0"]={"versions": [{"id": "FIG-95339ed87f7902d0", "releases": ["R1.3.0", "R1.5.1", "R17-03_R1.1.0", "R17-10_R1.2.0", "R18-03_R1.4.0", "R18-10_R4.4.0_R1.5.0", "R19-03", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Bitfeld- und Protokollformatdiagramm zur Spezifikation des 32-Bit-Feldes <code>Type Info (4 bytes)</code> innerhalb des AUTOSAR Log and Trace Protokolls (DLT). Es definiert die Bitbelegung zur Typisierung und Formatierung von Payload-Argumenten in Log- und Trace-Nachrichten auf Protokollebene.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm strukturiert das 4 Byte (32 Bit) breite Feld <code>Type Info</code> in vertikale Segmente mit Zeilen für <code>Name</code> und <code>Bit</code>:</p>\n<ul class=\"fig-list\"><li>Bit 0–3: <code>Type Length (TYLE)</code>\n</li><li>Bit 4: <code>Type Bool (Bool)</code>\n</li><li>Bit 5: <code>Type Signed (SINT)</code>\n</li><li>Bit 6: <code>Type Unsigned (UINT)</code>\n</li><li>Bit 7: <code>Type Float (FLOA)</code>\n</li><li>Bit 8: <code>Type Array (ARAY)</code>\n</li><li>Bit 9: <code>Type String (STRG)</code>\n</li><li>Bit 10: <code>Type Raw (RAWD)</code>\n</li><li>Bit 11: <code>Variable Info (VARI)</code>\n</li><li>Bit 12: <code>Fixed Point (FIXP)</code>\n</li><li>Bit 13: <code>Trace Info (TRAI)</code>\n</li><li>Bit 14: <code>Type Struct (STRU)</code>\n</li><li>Bit 15–17: <code>String Coding (SCOD)</code> (grau hinterlegt)\n</li><li>Bit 18–31: <code>reserved</code> (grau hinterlegt)\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Bitbelegungsdiagramm ohne dynamische Ablauf- oder Zustandsdarstellung. Die Bitfelder werden beim Serialisieren eines Nutzdatenparameters im Sender gesetzt und vom Empfänger zur Interpretation des folgenden Parameterwerts bitweise ausgewertet.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindende Bit-Feld-Definition für DLT-Pakete. Bit 0–14 definieren primäre Datentypen, Attribute und Längeninformationen als Flags bzw. Subfelder. Bit 15–17 kodieren die Zeichenkodierung (<code>String Coding</code>), während Bit 18–31 für zukünftige Protokollerweiterungen reserviert sind und bei der Übertragung entsprechend der Spezifikation maskiert bzw. ignoriert werden müssen.</p>"}, {"id": "FIG-b78be2b2fb8f5005", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Bitfeld- und Protokollformatdiagramm zur Spezifikation des 32-Bit-Feldes <code>Type Info (4 bytes)</code> innerhalb des AUTOSAR Log and Trace Protokolls (DLT). Es definiert die Bitbelegung zur Typisierung und Formatierung von Payload-Argumenten in Log- und Trace-Nachrichten auf Protokollebene.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm strukturiert das 4 Byte (32 Bit) breite Feld <code>Type Info</code> in vertikale Segmente mit Zeilen für <code>Name</code> und <code>Bit</code>:</p>\n<ul class=\"fig-list\"><li>Bit 0–3: <code>Type Length (TYLE)</code>\n</li><li>Bit 4: <code>Type Bool (Bool)</code>\n</li><li>Bit 5: <code>Type Signed (SINT)</code>\n</li><li>Bit 6: <code>Type Unsigned (UINT)</code>\n</li><li>Bit 7: <code>Type Float (FLOA)</code>\n</li><li>Bit 8: <code>Type Array (ARAY)</code>\n</li><li>Bit 9: <code>Type String (STRG)</code>\n</li><li>Bit 10: <code>Type Raw (RAWD)</code>\n</li><li>Bit 11: <code>Variable Info (VARI)</code>\n</li><li>Bit 12: <code>Fixed Point (FIXP)</code>\n</li><li>Bit 13: <code>Trace Info (TRAI)</code>\n</li><li>Bit 14: <code>Type Struct (STRU)</code>\n</li><li>Bit 15–17: <code>String Coding (SCOD)</code> (grau hinterlegt)\n</li><li>Bit 18–31: <code>reserved</code> (grau hinterlegt)\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Bitbelegungsdiagramm ohne dynamische Ablauf- oder Zustandsdarstellung. Die Bitfelder werden beim Serialisieren eines Nutzdatenparameters im Sender gesetzt und vom Empfänger zur Interpretation des folgenden Parameterwerts bitweise ausgewertet.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindende Bit-Feld-Definition für DLT-Pakete. Bit 0–14 definieren primäre Datentypen, Attribute und Längeninformationen als Flags bzw. Subfelder. Bit 15–17 kodieren die Zeichenkodierung (<code>String Coding</code>), während Bit 18–31 für zukünftige Protokollerweiterungen reserviert sind und bei der Übertragung entsprechend der Spezifikation maskiert bzw. ignoriert werden müssen.</p>"}, {"id": "FIG-f2670af4c2bb8070", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Bitfeld- und Protokollformatdiagramm zur Spezifikation des 32-Bit-Feldes <code>Type Info (4 bytes)</code> innerhalb des AUTOSAR Log and Trace Protokolls (DLT). Es definiert die Bitbelegung zur Typisierung und Formatierung von Payload-Argumenten in Log- und Trace-Nachrichten auf Protokollebene.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm strukturiert das 4 Byte (32 Bit) breite Feld <code>Type Info</code> in vertikale Segmente mit Zeilen für <code>Name</code> und <code>Bit</code>:</p>\n<ul class=\"fig-list\"><li>Bit 0–3: <code>Type Length (TYLE)</code>\n</li><li>Bit 4: <code>Type Bool (Bool)</code>\n</li><li>Bit 5: <code>Type Signed (SINT)</code>\n</li><li>Bit 6: <code>Type Unsigned (UINT)</code>\n</li><li>Bit 7: <code>Type Float (FLOA)</code>\n</li><li>Bit 8: <code>Type Array (ARAY)</code>\n</li><li>Bit 9: <code>Type String (STRG)</code>\n</li><li>Bit 10: <code>Type Raw (RAWD)</code>\n</li><li>Bit 11: <code>Variable Info (VARI)</code>\n</li><li>Bit 12: <code>Fixed Point (FIXP)</code>\n</li><li>Bit 13: <code>Trace Info (TRAI)</code>\n</li><li>Bit 14: <code>Type Struct (STRU)</code>\n</li><li>Bit 15–17: <code>Type Format (TYFM)</code>\n</li><li>Bit 18–23: <code>Type Precision (TYPR)</code>\n</li><li>Bit 24–31: <code>reserved</code> (grau hinterlegt)\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Bitbelegungsdiagramm ohne dynamische Ablauf- oder Zustandsdarstellung. Die Bitfelder werden beim Serialisieren eines Nutzdatenparameters im Sender gesetzt und vom Empfänger zur Interpretation des folgenden Parameterwerts bitweise ausgewertet.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindende Bit-Feld-Definition für DLT-Pakete. Bit 0–14 definieren primäre Datentypen, Attribute und Längeninformationen als Flags bzw. Subfelder. Bit 15–17 kodieren das Darstellungsformat (<code>Type Format</code>), Bit 18–23 die Genauigkeit (<code>Type Precision</code>). Bit 24–31 sind reserviert und bei der Übertragung entsprechend der Protokollvorgaben zu handhaben.</p>"}, {"id": "FIG-0649b6103d97e400", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Bitfeld- und Protokollformatdiagramm zur Spezifikation des 32-Bit-Feldes <code>Type Info (4 bytes)</code> innerhalb des AUTOSAR Log and Trace Protokolls (DLT). Es definiert die Bitbelegung zur Typisierung und Formatierung von Payload-Argumenten in Log- und Trace-Nachrichten auf Protokollebene.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm strukturiert das 4 Byte (32 Bit) breite Feld <code>Type Info</code> in vertikale Segmente mit Zeilen für <code>Name</code> und <code>Bit</code>:</p>\n<ul class=\"fig-list\"><li>Bit 0–3: <code>Type Length (TYLE)</code>\n</li><li>Bit 4: <code>Type Bool (Bool)</code>\n</li><li>Bit 5: <code>Type Signed (SINT)</code>\n</li><li>Bit 6: <code>Type Unsigned (UINT)</code>\n</li><li>Bit 7: <code>Type Float (FLOA)</code>\n</li><li>Bit 8: <code>Type Array (ARAY)</code>\n</li><li>Bit 9: <code>Type String (STRG)</code>\n</li><li>Bit 10: <code>Type Raw (RAWD)</code>\n</li><li>Bit 11: <code>Variable Info (VARI)</code>\n</li><li>Bit 12: <code>Fixed Point (FIXP)</code>\n</li><li>Bit 13: <code>Trace Info (TRAI)</code>\n</li><li>Bit 14: <code>Type Struct (STRU)</code>\n</li><li>Bit 15–17: <code>Type Format (TYFM)</code>\n</li><li>Bit 18–23: <code>Type Precision (TYPR)</code>\n</li><li>Bit 24–31: <code>reserved</code> (grau hinterlegt)\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Bitbelegungsdiagramm ohne dynamische Ablauf- oder Zustandsdarstellung. Die Bitfelder werden beim Serialisieren eines Nutzdatenparameters im Sender gesetzt und vom Empfänger zur Interpretation des folgenden Parameterwerts bitweise ausgewertet.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindende Bit-Feld-Definition für DLT-Pakete. Bit 0–14 definieren primäre Datentypen, Attribute und Längeninformationen als Flags bzw. Subfelder. Bit 15–17 kodieren das Darstellungsformat (<code>Type Format</code>), Bit 18–23 die Genauigkeit (<code>Type Precision</code>). Bit 24–31 sind reserviert und bei der Übertragung entsprechend der Protokollvorgaben zu handhaben.</p>"}], "trans": [{"from": "FIG-95339ed87f7902d0", "to": "FIG-b78be2b2fb8f5005", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-b78be2b2fb8f5005", "to": "FIG-f2670af4c2bb8070", "fr": "R20-11", "tr": "R21-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Bitfeld <code>String Coding (SCOD)</code> an Bit 15–17 ersetzt durch <code>Type Format (TYFM)</code>.\n</li><li>Bitfeld <code>Type Precision (TYPR)</code> an Bit 18–23 neu definiert.\n</li><li>Bitbereich <code>reserved</code> von Bit 18–31 auf Bit 24–31 verkürzt.\n</li></ul>"}, {"from": "FIG-f2670af4c2bb8070", "to": "FIG-0649b6103d97e400", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
